    "text1318": {
      "type": "string",
      "name": "text1318",
      "x-decorator": "FormItem",
      "x-decorator-props": {
        "layout": "wrap"
      },
      "title": "That's a great incentive for VIP users! To clarify, when VIP users recharge their linked game account, they not only receive a basic gift but also an additional UC gift exclusive to VIPs. The extra gift percentage increases with the VIP level:\n\n <br/>V1: Extra 3% UC gift\n <br/>V2: Extra 4% UC gift\n <br/>V3: Extra 5% UC gift\n <br/>V4: Extra 6% UC gift\n <br/>V5 to V8: Extra 7% UC gift\n <br/>For instance, a V8 user who recharges 600UC will receive an additional 42UC (which is 7% of 600UC). Along with the basic gift of 60UC, the user will receive a total of 702UC (600 + 60 + 42)."
    },
