    "text1745": {
      "type": "string",
      "name": "text1745",
      "x-decorator": "FormItem",
      "x-decorator-props": {
        "layout": "wrap"
      },
      "title": "1. 10 bonus points for every 60{coin_name} recharge or redemption; 100% bonus points for the first recharge or credit card recharge.\nFor example: if you recharge 60{coin_name}, meet the first time recharge and use credit card, you will get 10+10*200%=30 points.\n2. The bonus {coin_name} when users recharge will not participate in the bonus points."
    },
    "text1746": {
      "type": "string",
      "name": "text1746",
      "x-decorator": "FormItem",
      "x-decorator-props": {
        "layout": "wrap"
      },
      "title": "Only linked player ID can get extra {coin_name}"
    },
    "text1747": {
      "type": "string",
      "name": "text1747",
      "x-decorator": "FormItem",
      "x-decorator-props": {
        "layout": "wrap"
      },
      "title": "VIP{0} can get extra {1} {coin_name}"
    },
    "text1748": {
      "type": "string",
      "name": "text1748",
      "x-decorator": "FormItem",
      "x-decorator-props": {
        "layout": "wrap"
      },
      "title": "That's a great incentive for VIP users! To clarify, when VIP users recharge their linked game account, they not only receive a basic gift but also an additional {coin_name} gift exclusive to VIPs. The extra gift percentage increases with the VIP level:\n\n <br/>V1: Extra 3% {coin_name} gift\n <br/>V2: Extra 4% {coin_name} gift\n <br/>V3: Extra 5% {coin_name} gift\n <br/>V4: Extra 6% {coin_name} gift\n <br/>V5 to V8: Extra 7% {coin_name} gift\n <br/>For instance, a V8 user who recharges 600{coin_name} will receive an additional 42{coin_name} (which is 7% of 600{coin_name}). Along with the basic gift of 60{coin_name}, the user will receive a total of 702{coin_name} (600 + 60 + 42)."
    },
