  "text1021": "Redeem Record",
  "text1022": "VIP Level",
  "text1023": "Midasbuy&PUBGM membership growth system has 8 levels from V1 to V8, providing differentiated privileges and benefits for members of different levels.",
  "text1024": "VIP Level upgrade",
  "text1025": "The VIP level is linked to the player's cumulative number of UCs recharged: the user will be able to upgrade the membership level by recharging or redeeming UCs accordingly. (Users need to bind their accounts to view the VIP level)",
  "text1026": "Level",
  "text1028": "VIP Level FAQ",
  "text1029": "How do I upgrade my midasbuy X pubgm VIP level?",
  "text1030": "When a user links to a midsbuy account, the cumulative top-up/redemption amount of the account is recorded and the account is upgraded based on the cumulative number of UCs purchased.",
  "text1031": "Why is my vip level different than before?",
  "text1032": "Our VIP level system has been newly upgraded! For users who have recharged PUBGM: We will classify the new VIP level according to the cumulative number of UCs you have recharged and redeemed in PUBGM, and the criteria have been stated in [VIP Rules]. For users who have not recharged PUBGM: you will continue to enjoy the benefits provided by Midasbuy after the upgrade of Midasbuy's platform level ~ please look forward to more surprises!",
  "text1033": "Can I do not link the playerID?",
  "text1034": "If you don't link your account, you won't be able to see your vip level in pubgm and you won't be able to enjoy the corresponding benefits.",
  "text1035": "VIP Point",
  "text1036": "Users can obtain VIP points by top-up. VIP points can be exchanged for various rights and interests including game packages, etc., and participate in various VIP point activities in the midasbuy member center. The specific details are subject to the rights and interests exchange and activity page display.",
  "text1037": "Ways to obtain VIP points",
  "text1038": "Purchase to get VIP points",
  "text1039": "10 bonus points for every 60UC recharge or redemption; 100% bonus points for the first recharge or credit card recharge. For example: if you recharge 60UC, meet the first time recharge and use credit card, you will get 10+10*200%=30 points. 2. The bonus UC when users recharge will not participate in the bonus points.",
  "text1040": "Redeem can get VIP points",
  "text1041": "Redeeming UCs on the midasbuy platform also earns you points, with 10 points for every 60 UCs",
  "text1042": "Participating activities can get VIP points",
  "text1043": "Points can also be earned by participating in activities on the midasbuy platform, and you can refer to the rules for each activity for details on how to get points.",
  "text1044": "The validity period of VIP points",
  "text1045": "The validity period of the VIP points that the user has received is 12 natural months from the month of receipt. VIP points that are not used within the validity period will be automatically invalidated upon expiration. For example: VIP points earned from November 1 to 30, 2022, will be valid until 23:59:59 on November 30, 2023.",
  "text1046": "VIP points FAQ",
  "text1047": "How do I receive and use Midasbuy* PUBGM vip points?",
  "text1048": "Midasbuy* PUBGM vip points will be recorded under your playerID, you can accumulate the points by recharging, redeeming or doing tasks; at the same time, you need to bind your midasbuy account with your playerID before you can use them.",
  "text1049": "Can I transfer my Midasbuy*PUBGM vip points?",
  "text1050": "Midasbuy* PUBGM vip points transfer to other gaming accounts is not supported at this time.",
  "text1051": "Other notes",
  "text1052": "If the user takes any improper means such as taking prize brushing software, hiring others to participate, or has any illegal or illicit behaviors, we have the right to disqualify the user from obtaining the vip points, and the vip points that have been collected will be deducted back.",
  "text1053": "If I change my linked account, will my points be reduced?",
  "text1054": "Dear users, the points you earn by recharging will be accumulated under your game account, so changing the bound account will not lead to a decrease in [points earned by recharging]!",
  "text1055": "Purchase Bonus",
  "text1056": "Unlock Rich VIP Benefits!​​",
  "text1057": "Shop More on Midasbuy, Unlock More Privileges!",
  "text1058": "Upgrade to VIP",
  "text1059": "{count} Privileges",
  "text1060": "Extra Bonus UC",
  "text1061": "That's a great incentive for VIP users! To clarify, when VIP users recharge their linked game account, they not only receive a basic gift but also an additional UC gift exclusive to VIPs. The extra gift percentage increases with the VIP level",
  "text1062": "Extra bonus ratio",
