  "text1298": "Your Personal Passcode is the only thing that identifies you as a respected SuperCore player. You can use this passcode to link your social media account to your game account, so that your Personal Assistant can also provide you with any answers related to the game and account on other social platforms. You can also unlink your account at any time. Once you successfully link your account or if you don't link it within 24 hours, the passcode becomes invalid. If that happens, please enter the page again to obtain a new passcode.",
  "text1299": "Error!",
  "text1300": "Link Your",
  "text1301": "Personal Passcode",
  "text1302": "Tap to link your social media account and enjoy the services of your exclusive in-game Personal Assistant",
  "text1303": "Not Linked",
  "text1304": "Link Now",
  "text1305": "ABOUT PERSONAL PASSCODE",
  "text1306": "iknow",
  "text1307": "Your current account has not yet unlocked the VIP premium store",
