  "text1311": "`errorMap_${data.error_code}`",
  "text1312": "VIP POINTS",
  "text1313": "Reach a higher VIP level to unlock this privilege.",
  "text1315": "VIP DISCRIPTION",
  "text1318": "That's a great incentive for VIP users! To clarify, when VIP users recharge their linked game account, they not only receive a basic gift but also an additional UC gift exclusive to VIPs. The extra gift percentage increases with the VIP level:\n\n <br/>V1: Extra 3% UC gift\n <br/>V2: Extra 4% UC gift\n <br/>V3: Extra 5% UC gift\n <br/>V4: Extra 6% UC gift\n <br/>V5 to V8: Extra 7% UC gift\n <br/>For instance, a V8 user who recharges 600UC will receive an additional 42UC (which is 7% of 600UC). Along with the basic gift of 60UC, the user will receive a total of 702UC (600 + 60 + 42).",
  "text1319": "Go To VIP Center",
  "text1320": "Switch to Redeem Code",
  "text1321": "Switch to Cdkey Code",
  "text1322": "2. If you have any question or you need after-sales service, please contact redeem dealer where you buy the vouchers.",
