  "text1324": "Purchase eligibility has changed due to updated information. Please try redeeming again.",
  "text1325": "Advanced Room Card: 7-Day",
  "text1326": "Rating Protection Card",
  "text1327": "Priority in responding to your questions",
  "text1328": "Exclusive one-on-one support",
  "text1329": "Latest news and walkthroughs",
