  "text1367": "Auto Subscription",
  "text1368": "You're about to recharge {0} to account: {1} <br /> (Player ID: {2})",
  "text1369": "LINK YOUR PLAYER ID TO ENJOY VIP BENEFITS!",
  "text1370": "VIP GET UC",
  "text1371": "LINK NOW",
  "text1372": "Learn more about VIP",
  "text1375": "VIP Get",
  "text1379": "Mira is thinking...",
  "text1380": "Processing...",
  "text1381": "Helpful",
  "text1382": "Not Helpful",
  "text1383": "Bind",
  "text1384": "Transcribing...",
  "text1385": "Please enable microphone permissions first.",
  "text1386": "You previously denied recording permissions. Please follow the steps below to enable it so we can assist you:<br/>Click the [icon] on the left side of the browser address bar to access site settings.",
  "text1387": "Switch the microphone option to \"Allow.\"",
  "text1388": "Refresh the current page to apply the changes.",
  "text1390": "Chat With Mira",
  "text1391": "This page is designed for in-app use",
  "text1392": "VIP 3%-7% Extra Bonus",
  "text1393": "IN-APP SHOP",
  "text1394": "CHOOSE WHERE TO BUY",
  "text1395": "Midasbuy Shop",
  "text1553": "VIP Weekly Gifts",
  "text1554": "While your VIP Privileges are active, claim your free weekly gifts. You must reach the corresponding VIP Level to unlock each tier's gifts. Each tier can be claimed once per week, and higher VIP Levels unlock increasingly valuable gift contents. Claim counts reset every Monday at 00:00 UTC+0. Rewards will be delivered to your in-game inbox.",
  "text1556": "While your VIP Privileges are active, purchase Super Value Weekly Packs at a discount. You must reach the corresponding VIP Level to unlock that tier and all lower-tier Packs. Each tier can be purchased once per week, and higher VIP Levels unlock more Packs with richer contents. Purchase counts reset every Monday at 00:00 UTC+0. Rewards will be delivered to your in-game inbox.",
  "text1557": "VIP Point Bonus",
  "text1558": "While your VIP Privileges are active, earn bonus VIP Points on every purchase made through the Midasbuy platform. VIP 3 - VIP 4 receive a +5% bonus, VIP 5 - VIP 6 receive a +10% bonus, VIP 7 receives a +20% bonus, and VIP 8 receives a +30% bonus. The higher your VIP Level, the more Points you earn per purchase. VIP Points can be spent on the Wheel of Fortune and other events for additional rewards.",
  "text1561": "While your VIP Privileges are active, claim an exclusive limited-time VIP Frame each month to make your profile stand out. VIP 3 - VIP 5 can claim the 31-day Frost Gleam Frame, VIP 6 - VIP 7 can claim the 31-day Aqua Radiance Frame, and VIP 8 can claim the 31-day Golden Wing Crown Frame. Claim counts reset on the 1st of each month at 00:00 UTC+0. Rewards will be delivered to your in-game inbox.",
  "text1563": "While your VIP Privileges are active, claim an exclusive limited-time VIP Chat Bubble each month to show off your personal style. VIP 5 - VIP 6 can claim the 31-day Frost Whisper Chat Bubble, VIP 7 can claim the 31-day Aqua Oath Chat Bubble, and VIP 8 can claim the 31-day Golden Wing Decree Chat Bubble. Claim counts reset on the 1st of each month at 00:00 UTC+0. Rewards will be delivered to your in-game inbox.",
  "text1565": "While your VIP Privileges are active, claim an exclusive limited-time VIP Title each month to display your prestigious status. VIP 8 can claim the 31-day Golden Wing Ace Title. Claim counts reset on the 1st of each month at 00:00 UTC+0. Rewards will be delivered to your in-game inbox.",
  "text1566": "Unlock",
  "text1567": "The Midasbuy & AOEM membership growth system has 8 levels from V1 to V8, offering differentiated privileges and benefits. Your VIP level depends on the total paid amount recharged on the midasbuy webpage (1 USD = 1 VIP EXP).",
  "text1568": "Different levels grant different privileges, which can only be enjoyed after activation.",
  "text1569": "Activating a VIP Level",
  "text1570": "When your EXP earned in a calendar month reaches the required threshold, your VIP privilege activation period is extended by 31 days. The EXP requirement varies by VIP level.",
  "text1571": "EXP Range [",
  "text1572": "EXP Range )",
  "text1573": "Activate EXP",
  "text1574": "How do I upgrade my midasbuy X AOEM VIP level?",
  "text1575": "When a user links a midasbuy account, the cumulative top-up amount (in USD) is recorded. The account’s VIP level (V1–V8) is then determined based on the total paid amount, at the rate of 1 USD = 1 VIP EXP.",
  "text1576": "How do they decide my starting level?",
  "text1578": "If you don't link your account, you won't be able to see your vip level in AOEM and you won't be able to enjoy the corresponding benefits.",
  "text1579": "Users can obtain VIP points through top-ups, watching live streams, or participating in Midasbuy's exclusive marketing campaigns. VIP points can be used to enter point-based lucky draws, allowing users to obtain various benefits such as in-game items, and to participate in various VIP point activities in the midasbuy member center. Specific details are subject to the benefits exchange and activity page displays.",
  "text1580": "Earn 10 bonus points for every 1 USD recharged.",
  "text1581": "Points can also be earned by watching live streams, or participating in activities on the midasbuy platform, and you can refer to the rules for each activity for details on how to get points.",
  "text1582": "The validity period of the VIP points that the user has received is 12 natural months from the month of receipt. VIP points that are not used within the validity period will be automatically invalidated upon expiration. For example: VIP points earned from November 1 to 30, 2025, will be valid until 23:59:59 on November 30, 2026.",
  "text1583": "How do I receive and use Midasbuy*AOEM vip points?",
  "text1584": "Midasbuy*AOEM vip points will be recorded under your playerID, you can accumulate the points by recharging or doing tasks; at the same time, you need to bind your midasbuy account with your playerID before you can use them.",
  "text1585": "Can I transfer my Midasbuy*AOEM vip points?",
  "text1586": "Midasbuy*AOEM vip points transfer to other gaming accounts is not supported at this time.",
