  "text1683": "About midasbuy vip",
  "text1684": "After recharging on Midasbuy platform, you can obtain the platform membership status and enjoy the platform privileges. Currently, the platform's level mechanism has been optimised and no longer displays your platform vip level, but the points you have earned from doing tasks will still be retained and can be used to participate in point draws. At the same time, we will gradually implement the official exclusive joint membership with the game, and will display the vip level of the exclusive members of the game, please stay tuned!",
  "text1685": "midasbuy vip privileges",
  "text1686": "After the new upgrade of Midasbuy VIP system, the rights and interests you previously enjoyed remain unchanged: including member-exclusive rights such as points tasks, points lottery, points redemption, customer service support, etc.",
  "text1687": "Midasbuy x games vip",
  "text1688": "About Midasbuy x game vip",
  "text1689": "Midasbuy, as an open recharge platform, launched the joint membership of Midasbuy x game",
  "text1690": "Midasbuy x PUBGM vip",
  "text1691": "Enjoy various privileges and benefits",
