  "text1704": "Buy more at midasbuy to enjoy more game privileges!",
  "text1705": "VIP privileges and rules are newly upgraded, click to learn more",
  "text1706": "Claim Free weekly gifts, higher VIP Levels unlock increasingly valuable gift contents. ",
  "text1707": "Purchase Packs at a discount, higher VIP Levels unlock more Packs with richer contents. ",
  "text1708": "The higher your VIP Level, the more Points per purchase. Points redeem extra rewards via events.",
  "text1709": "Claim an exclusive limited-time VIP Frame each month to make your profile stand out. ",
